def transform(grid):
    H=len(grid); W=len(grid[0])
    g=[row[:] for row in grid]
    seed=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==3][0]
    r,c=seed; d=0; dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    length=2
    while True:
        end=False
        for _ in range(length):
            nr,nc=r+dirs[d][0],c+dirs[d][1]
            if not(0<=nr<H and 0<=nc<W) or grid[nr][nc]==2:
                end=True; break
            r,c=nr,nc; g[r][c]=3
        else:
            d=(d+1)%4
            continue
        break
    return g

